+// Corrección (ADR-001): los movimientos no se borran; se agrega el inverso del movimiento erróneo,
+// de modo que el stock queda como si no se hubiera hecho. Respeta RF-002 (deshacer un ingreso ya
+// consumido lanza "Stock insuficiente"). Un movimiento no se corrige dos veces.
+export function corregirMovimiento(movimientos, indice) {
+  if (!Number.isInteger(indice) || indice < 0 || indice >= movimientos.length)
+    throw new RangeError(`Índice de movimiento inválido: ${indice}`);
+  const original = movimientos[indice];
+  if (original.corrige !== undefined) throw new Error("No se puede corregir un movimiento de corrección");
+  if (movimientos.some((m) => m.corrige === indice)) throw new Error(`El movimiento ${indice} ya fue corregido`);
+  const { articulo, almacen, cantidad } = original;
+  return registrarMovimiento(movimientos, {
+    tipo: original.tipo === "ingreso" ? "egreso" : "ingreso",
+    articulo,
+    almacen,
+    cantidad,
+    corrige: indice,
+  });
+}
